import hmac,hashlib,itertools,re
target_sigs={'bffeb3c5288680d28188604f96d8f2b1ac5c7389c01fe5265b0cb0ad71364c88':6,'29ad673946f1cf2fb7ee1aea184a9efc1ec00fdca9efc528faf4af8d197915f1':7}
import json
recs=json.load(open('requests/sample-requests.json'))
def canon(r,o):
    t=r['target'];p,_,q=t.partition('?')
    pairs=[(x.split('=',1)+[''])[:2] for x in q.split('&')] if q else []
    if o['qsort']=='name': pairs.sort(key=lambda x:x[0])
    else: pairs.sort(key=lambda x:(x[0],x[1]))
    qs='&'.join(n+'='+v for n,v in pairs)
    hs=[(n.lower(),v) for n,v in r['headers']]
    if o['hset']=='all': hs=[h for h in hs if h[0]!='authorization']
    else: hs=[h for h in hs if h[0].startswith('x-gw-') or (o['hset']=='gwct' and h[0]=='content-type')]
    if o['hv']=='strip': hs=[(n,v.strip(' \t')) for n,v in hs]
    elif o['hv']=='collapse': hs=[(n,re.sub('[ \t]+',' ',v.strip(' \t'))) for n,v in hs]
    hs.sort(key=lambda x:x[0])
    b=r.get('body')
    if o['body']=='sha': bh=hashlib.sha256((b or '').encode()).hexdigest()
    else: bh='UNSIGNED' if not b else hashlib.sha256(b.encode()).hexdigest()
    s='\n'.join([r['method'].upper(),p,qs,'\n'.join(n+':'+v for n,v in hs),o['sep'].join(n for n,v in hs),bh])
    return s+('\n' if o['term'] else '')
opts=dict(qsort=['name','nv'],hset=['all','gw','gwct'],hv=['raw','strip','collapse'],body=['sha','uns'],sep=[';',','],term=[0,1],key=['whole','strip'])
for combo in itertools.product(*opts.values()):
    o=dict(zip(opts,combo))
    for i in (5,6):
        r=recs[i];kid=r['headers'][0][1]
        k=open(f'keys/{kid}.key','rb').read()
        if o['key']=='strip': k=k.rstrip(b'\n')
        sig=hmac.new(k,canon(r,o).encode(),hashlib.sha256).hexdigest()
        if sig in target_sigs: print(i+1,o)
